@end
static LBXLicenseOwner *Source(LBXLicenseVault *vault){LBXLicenseOwner *owner=[[LBXLicenseOwner alloc] initWithVault:vault];[owner testUseProtocol:PendingProtocol.class publicKey:TestLicensePublicDER() keyID:TestLicenseKeyID()];return owner;}
static NSDictionary *License(LBXLicenseOwner *owner,NSString *operation){dispatch_semaphore_t done=dispatch_semaphore_create(0);__block NSDictionary *reply;[owner handleRequest:LBXLicenseIPCRequest(operation,[operation isEqual:@"activate"]?@"AAAA-BBBB-CCCC-DDDD":nil) completion:^(NSDictionary *result){reply=result;dispatch_semaphore_signal(done);}];Check(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC)),@"bounded genuine signed license response");return reply;}
static void Authorize(LBXLicenseOwner *owner){mode=@"active";Check([License(owner,@"validate")[@"result"] isEqual:@"active"]&&[owner sourceAuthorizationCurrent],@"fresh genuine signed admission before root metadata operation");}
static NSDictionary *Send(LBXContainerRootMutationOwner *owner,NSDictionary *request){Check(request&&LBXContainerMutationIPCValidateRequest(request,LBXContainerMutationIPCClock()),@"strict typed mutation request");dispatch_semaphore_t done=dispatch_semaphore_create(0);__block NSDictionary *reply;__block NSUInteger count=0;[owner handleRequest:request completion:^(NSDictionary *result){reply=result;count++;dispatch_semaphore_signal(done);}];Check(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,5*NSEC_PER_SEC))&&count==1,@"one bounded root mutation reply");Check(LBXContainerMutationIPCValidateReply(reply,request,LBXContainerMutationIPCClock()),@"strict root mutation reply and runtimeAccepted false");return reply;}
static NSDictionary *Call(LBXContainerRootMutationOwner *owner,NSString *operation,NSDictionary *arguments){return Send(owner,LBXContainerMutationIPCRequest(operation,arguments));}
static NSDictionary *Choices(NSString *name){return @{@"name":name,@"applications":@[@"com.burbn.instagram"],@"manualIdentifiers":NSNull.null,@"proxyReference":@""};}
static NSDictionary *StageArguments(NSString *epoch,NSString *request,NSDictionary *choices){return @{@"expectedEmptyEpoch":epoch,@"stageRequestID":request,@"choices":choices};}
static NSDictionary *Token(NSDictionary *slot){return @{@"token":slot[@"token"],@"epoch":slot[@"epoch"]};}
static NSDictionary *Read(NSString *path){NSData *data=[NSData dataWithContentsOfFile:path];return data?[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]:nil;}
static BOOL Write(NSString *path,id value){NSData *data=[value isKindOfClass:NSData.class]?value:[NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingSortedKeys|NSJSONWritingWithoutEscapingSlashes error:nil];return data&&[data writeToFile:path atomically:NO]&&!chmod(path.fileSystemRepresentation,0600);}
